        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    if hp <= 1 or no_water_days >= 2:
        target = max(64, highest_prev + 3)
        return min(budget, target)

    if hp <= 2 or no_water_days >= 1:
        target = max(54, highest_prev + 2)
        return min(budget, target)

    if slack >= WATER_REQ:
        base = 18
        if desperate_count > 0:
            base = 24
        return min(budget, base)

    if slack >= 0:
        target = max(30, avg_prev + 1)
        if rich_count >= 2:
            target += 4
        return min(budget, target)

    target = max(42, highest_prev + 1.5)
    if desperate_count >= 2:
        target += 5
    if rich_count >= 2:
