def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # Base safety: if we're in danger, bid aggressively but capped by budget.
    danger = (my_hp <= 2.0) or (my_no_water_days >= 2)

    # Extract yesterday bids from immediate previous_trace only.
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # If no info, bid based on supply pressure.
    if not prev_bids:
        # Higher supply -> lower bid; lower supply -> higher bid.
        supply_norm = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
        supply_norm = max(0.0, min(1.0, supply_norm))
        if danger:
            target = DAILY_SALARY * (0.75 + 0.15 * (1.0 - supply_norm))
        else:
            target = DAILY_SALARY * (0.45 + 0.20 * (1.0 - supply_norm))
        return max(0.0, min(my_budget, target))

    highest_prev_bid = max(prev_bids)
    avg_prev_bid = sum(prev_bids) / float(len(prev_bids))

    # High-pressure response: outbid slightly if they were bidding near salary.
    high_threshold = DAILY_SALARY * 0.85
    mid_threshold = DAILY_SALARY * 0.55

    if highest_prev_bid >= high_threshold:
        # They likely needed water badly; secure by bidding just above.
        if my_hp > 3.0:
            target = highest_prev_bid + 2.0
        else:
            target = highest_prev_bid + 6.0
    elif highest_prev_bid >= mid_threshold:
        # Moderate contention: bid around average with a small premium.
        target = max(avg_prev_bid + 1.5, DAILY_SALARY * 0.50)
        if danger:
            target = max(target, DAILY_SALARY * 0.65)
    else:
        # Low contention: bid enough to win against likely low bids.
        supply_norm = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
        supply_norm = max(0.0, min(1.0, supply_norm))
        # Lower supply -> slightly higher bid.
        target = DAILY_SALARY * (0.48 + 0.20 * (1.0 - supply_norm))
        if danger:
            target = max(target, DAILY_SALARY * 0.62)

    # Convert target into a budget-safe bid.
    bid = min(my_budget, float(target))

    # If budget is extremely low, still bid something non-negative.
    if bid < 0.0:
        bid = 0.0

    return bid
